+        return strBuilder.get().utf8ToString();
+    }
+
+    private static int numUtf8Bytes(int c) {
+        if (c < 128) {
+            return 1;
+        }
+        if (c < 2048) {
+            return 2;
+        }
+        if (c < 65536) {
+            return 3;
+        }
+        return 4;
+    }
+
+}

